def hidden_rule_fn(state):
    n = len(state)
    if n < 2:
        return state

    def is_prime(k):
        if k < 2:
            return False
        for i in range(2, int(k**0.5) + 1):
            if k % i == 0:
                return False
        return True

    a = state[-1]
    b = state[-2]

    if is_prime(n):
        # thraxgate-index: use ploon-XOR
        new_val = (a ^ b) % 7
    else:
        # not a thraxgate-index: use grolp-sum
        new_val = (a + b + 3) % 7

    return state + [new_val]
